  const chartSvg = d3.select('#bubble-chart');
  const width = +chartSvg.attr('width');
  const height = +chartSvg.attr('height');

  const tooltip = d3.select('#tooltip');

  const formatMarketCap = (value) => {
    if (value == null || Number.isNaN(value)) return '—';
    const abs = Math.abs(value);
    const units = [
      { label: 'T', value: 1e12 },
      { label: 'B', value: 1e9 },
      { label: 'M', value: 1e6 },
      { label: 'K', value: 1e3 },
    ];
    for (const u of units) {
      if (abs >= u.value) return `${d3.format(',.2f')(value / u.value)}${u.label}`;
    }
    return d3.format(',.0f')(value);
  };

  const sectorCenters = (sectors, w, h) => {
    const n = sectors.length;
    const cols = Math.ceil(Math.sqrt(n));
    const rows = Math.ceil(n / cols);

    const margin = 120;
    const gridW = Math.max(1, w - margin * 2);
    const gridH = Math.max(1, h - margin * 2);
    const cellW = gridW / cols;
    const cellH = gridH / rows;

    const centers = new Map();
    sectors.forEach((sector, i) => {
      const col = i % cols;
      const row = Math.floor(i / cols);
      centers.set(sector, {
        x: margin + cellW * (col + 0.5),
        y: margin + cellH * (row + 0.5),
      });
    });
    return centers;
  };

  const normalizeTicker = (t) => String(t || '').trim();

  const selectTicker = (ticker) => {
    const key = normalizeTicker(ticker);

    d3.selectAll('.bubble').classed('selected', (d) => normalizeTicker(d.ticker) === key);
    d3.selectAll('.table-row').classed('selected', function () {
      return d3.select(this).attr('data-ticker') === key;
    });

    const row = document.querySelector(`.table-row[data-ticker="${CSS.escape(key)}"]`);
    if (row) {
      row.scrollIntoView({ block: 'nearest', inline: 'nearest' });
    }
  };

  const clearSelection = () => {
    d3.selectAll('.bubble').classed('selected', false);
    d3.selectAll('.table-row').classed('selected', false);
  };

  Promise.all([
    d3.json('data/stocks.json'),
  ]).then(([stocks]) => {
    const data = stocks
      .map((d) => ({
        ticker: normalizeTicker(d.ticker),
        name: d.name,
        sector: d.sector || 'Unknown',
        marketCap: d.marketCap == null ? null : +d.marketCap,
        isEtf: d.marketCap == null,
      }))
      .sort((a, b) => d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker));

    const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(d3.ascending);
    const color = d3.scaleOrdinal().domain(sectors).range(d3.schemeTableau10.concat(d3.schemeSet3).slice(0, sectors.length));

    const centers = sectorCenters(sectors, width, height);

    const marketCaps = data.filter((d) => !d.isEtf).map((d) => d.marketCap);
    const capExtent = d3.extent(marketCaps);

    const radiusScale = d3
      .scaleSqrt()
      .domain(capExtent)
      .range([10, 56]);

    const etfRadius = 18;

    data.forEach((d) => {
      d.r = d.isEtf ? etfRadius : radiusScale(d.marketCap);
      const c = centers.get(d.sector) || { x: width / 2, y: height / 2 };
      d.x = c.x;
      d.y = c.y;
    });

    const legend = d3.select('#legend');
    const legendItems = legend
      .selectAll('div.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    legendItems
      .append('div')
      .attr('class', 'legend-color')
      .style('background', (d) => color(d));

    legendItems
      .append('div')
      .text((d) => d);

    const tableBody = d3.select('#stock-table-body');

    const rows = tableBody
      .selectAll('tr')
      .data(data, (d) => d.ticker)
      .enter()
      .append('tr')
      .attr('class', 'table-row')
      .attr('data-ticker', (d) => d.ticker)
      .on('click', (event, d) => {
        event.stopPropagation();
        selectTicker(d.ticker);
      });

    rows.append('td').text((d) => d.ticker);
    rows.append('td').text((d) => d.name);
    rows.append('td').text((d) => d.sector);
    rows.append('td').text((d) => formatMarketCap(d.marketCap));

    const node = chartSvg
      .selectAll('g.node')
      .data(data, (d) => d.ticker)
      .enter()
      .append('g')
      .attr('class', 'node')
      .attr('data-ticker', (d) => d.ticker)
      .on('click', (event, d) => {
        event.stopPropagation();
        selectTicker(d.ticker);
      })
      .on('mouseover', (event, d) => {
        if (d.isEtf) return;
        tooltip
          .classed('visible', true)
          .html(`<div><strong>${d.ticker}</strong></div><div>${d.name}</div><div>${d.sector}</div>`);
      })
      .on('mousemove', (event, d) => {
        if (d.isEtf) return;
        const offset = 14;
        tooltip
          .style('left', `${event.offsetX + offset}px`)
          .style('top', `${event.offsetY + offset}px`);
      })
      .on('mouseout', (event, d) => {
        if (d.isEtf) return;
        tooltip.classed('visible', false);
      });

    node
      .append('circle')
      .attr('class', 'bubble')
      .attr('r', (d) => d.r)
      .attr('fill', (d) => color(d.sector));

    node
      .append('text')
      .attr('text-anchor', 'middle')
      .attr('dy', '0.35em')
      .text((d) => d.ticker);

    chartSvg.on('click', () => clearSelection());
    d3.select('body').on('click', () => clearSelection());

    const simulation = d3
      .forceSimulation(data)
      .force('charge', d3.forceManyBody().strength(-14))
      .force(
        'x',
        d3.forceX((d) => (centers.get(d.sector) || { x: width / 2 }).x).strength(0.22)
      )
      .force(
        'y',
        d3.forceY((d) => (centers.get(d.sector) || { y: height / 2 }).y).strength(0.22)
      )
      .force('collide', d3.forceCollide((d) => d.r + 2).iterations(3))
      .alpha(1)
      .alphaDecay(0.04)
      .on('tick', () => {
        node.attr('transform', (d) => {
          d.x = Math.max(d.r, Math.min(width - d.r, d.x));
          d.y = Math.max(d.r, Math.min(height - d.r, d.y));
          return `translate(${d.x},${d.y})`;
        });
      });

    const settleTicks = 260;
    for (let i = 0; i < settleTicks; i += 1) simulation.tick();
    simulation.stop();
  });
})();
